import{Z as t,e as o,f as n,a0 as r}from"./chunks/framework.DmpHOl9T.js";const g=JSON.parse('{"title":"Project Config, Environment, and Control Panel Settings","description":"","frontmatter":{},"headers":[],"relativePath":"guides/configuration/project-config-environment-and-control-panel-settings.md","filePath":"guides/configuration/project-config-environment-and-control-panel-settings.md","lastUpdated":1782532814000}'),i={name:"guides/configuration/project-config-environment-and-control-panel-settings.md"};function a(s,e,c,d,l,p){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="project-config-environment-and-control-panel-settings" tabindex="-1">Project Config, Environment, and Control Panel Settings <a class="header-anchor" href="#project-config-environment-and-control-panel-settings" aria-label="Permalink to &quot;Project Config, Environment, and Control Panel Settings&quot;">​</a></h1><p>Formie does not store everything in one place. Some settings version with your Craft project, some live in <code>config/formie.php</code> on each server, and some stay in the database so privileged admins can edit them in production even when <code>allowAdminChanges</code> is off.</p><p>This guide gives you a mental model for <strong>where to change a setting</strong> and <strong>what happens when you deploy</strong> — so staging promotions do not silently break captchas, spam rules, or integrations on production.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li><a href="/get-started/configuration">Configuration</a> — full list of <code>formie.php</code> options</li><li><a href="/forms/spam-protection">Spam Protection</a></li><li>Craft <a href="https://craftcms.com/docs/5.x/system/project-config.html" target="_blank" rel="noreferrer">project config</a> basics</li></ul><h2 id="the-problem-this-solves" tabindex="-1">The Problem This Solves <a class="header-anchor" href="#the-problem-this-solves" aria-label="Permalink to &quot;The Problem This Solves&quot;">​</a></h2><p>These situations usually mean a setting is in the wrong scope — or you expected it to sync when it does not:</p><ul><li>Production Turnstile keys disappeared after <code>project-config/sync</code></li><li>Spam keywords on staging never showed up on production</li><li>OAuth integrations worked on staging but fail after a database copy</li><li>A form group change deployed, but the contact form layout did not</li></ul><p>The fix is not memorising every table and YAML key. It is knowing which of three scopes owns the thing you are changing.</p><h2 id="three-scopes-—-one-sentence-each" tabindex="-1">Three Scopes — One Sentence Each <a class="header-anchor" href="#three-scopes-—-one-sentence-each" aria-label="Permalink to &quot;Three Scopes — One Sentence Each&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>One-line summary</th></tr></thead><tbody><tr><td><strong>Project config</strong></td><td>Structure you want in git — form groups, project stencils, statuses, reports</td></tr><tr><td><strong>Environment config</strong></td><td>Developer-controlled behaviour in <code>config/formie.php</code> — queues, defaults, dev tunnels</td></tr><tr><td><strong>Control panel settings</strong></td><td>Secrets and policy admins edit in the CP — spam keywords, captcha keys, integration credentials</td></tr></tbody></table><p>Forms themselves (fields, notifications, layout) are <strong>database content</strong>. They do not move with project config alone. Use <a href="/guides/control-panel-admin/import-and-export-between-environments">Import and export between environments</a> to promote form structure.</p><h2 id="walkthrough-—-promoting-staging-to-production" tabindex="-1">Walkthrough — Promoting Staging to Production <a class="header-anchor" href="#walkthrough-—-promoting-staging-to-production" aria-label="Permalink to &quot;Walkthrough — Promoting Staging to Production&quot;">​</a></h2><p>Imagine you finished work on staging and you are about to deploy. Here is what each scope does in that moment.</p><h3 id="_1-project-config-syncs-structure" tabindex="-1">1. Project Config Syncs Structure <a class="header-anchor" href="#_1-project-config-syncs-structure" aria-label="Permalink to &quot;1. Project Config Syncs Structure&quot;">​</a></h3><p>When production runs <code>project-config/sync</code>, Formie updates versioned resources such as:</p><ul><li>Form groups (including which sites a group applies to)</li><li>Project stencils</li><li>Submission and form statuses</li><li>Reports and scheduled report definitions</li></ul><p>These are the things your team typically wants identical across environments — checked into <code>config/project/</code> and deployed with Craft.</p><p>Individual forms still point at a group by UID in the database; the group definition comes from project config.</p><h3 id="_2-environment-config-applies-on-the-server" tabindex="-1">2. Environment Config Applies on the Server <a class="header-anchor" href="#_2-environment-config-applies-on-the-server" aria-label="Permalink to &quot;2. Environment Config Applies on the Server&quot;">​</a></h3><p><code>config/formie.php</code> is not synced by project config. Each environment reads its own file (or env-specific sections within it).</p><p>Typical per-environment differences:</p><ul><li><code>paymentWebhookProxyUrl</code> — dev tunnel vs real URLs on production</li><li><code>redirectUri</code> — OAuth callback base URL</li><li><code>useQueueForNotifications</code> / <code>useQueueForIntegrations</code> — queue behaviour</li><li><code>formDefaults</code> — default submit method, retention, and similar plugin-wide defaults</li></ul><p>See <a href="/get-started/configuration">Configuration</a> for every option. The point for deployment: <strong>changing <code>formie.php</code> on staging does nothing to production until you deploy that file</strong>.</p><h3 id="_3-control-panel-settings-stay-environment-local" tabindex="-1">3. Control Panel Settings Stay Environment-Local <a class="header-anchor" href="#_3-control-panel-settings-stay-environment-local" aria-label="Permalink to &quot;3. Control Panel Settings Stay Environment-Local&quot;">​</a></h3><p>Spam keywords, captcha provider secrets, and integration API keys live in dedicated database tables — <strong>Settings → Spam Protection</strong> and the integrations control panel — not in <code>plugins.formie.settings</code> project YAML.</p><p>That is deliberate:</p><ul><li>Privileged admins can update production captcha keys when the CP is otherwise read-only</li><li>Secrets do not land in git through project config exports</li><li>Some rows can be project-scoped defaults (seeded on deploy) while site-scoped rows stay local</li></ul><p>So after <code>project-config/sync</code>, <strong>these database rows are not replaced wholesale</strong>. If you copied a staging database to production, you may have copied staging secrets — which is often wrong. Re-enter production captcha keys and reconnect OAuth integrations on the target environment.</p><p>For keyword syntax and examples, see <a href="/guides/configuration/spam-keywords-in-detail">Spam keywords in detail</a>.</p><h3 id="_4-forms-do-not-ride-along-with-project-config" tabindex="-1">4. Forms Do Not Ride Along with Project Config <a class="header-anchor" href="#_4-forms-do-not-ride-along-with-project-config" aria-label="Permalink to &quot;4. Forms Do Not Ride Along with Project Config&quot;">​</a></h3><p>Form layout, notifications, fields, and per-site label overrides are database content. Promoting them is a separate step — export JSON on staging, import on production — not something project config handles.</p><p>Site <strong>availability</strong> for forms is tied to form group site policy (project config) plus <code>elements_sites</code> when you save a form. The form&#39;s fields and messages are still database rows.</p><h2 id="decision-guide-—-where-do-i-change-this" tabindex="-1">Decision Guide — Where Do I Change This? <a class="header-anchor" href="#decision-guide-—-where-do-i-change-this" aria-label="Permalink to &quot;Decision Guide — Where Do I Change This?&quot;">​</a></h2><p>Use this when you know <em>what</em> you want to change but not <em>where</em>:</p><table tabindex="0"><thead><tr><th>I want to change…</th><th>Where</th></tr></thead><tbody><tr><td>Default submit method for new forms</td><td><code>formDefaults</code> in <code>formie.php</code>, or <strong>Settings → Defaults</strong></td></tr><tr><td>Spam keywords</td><td><strong>Settings → Spam Protection</strong></td></tr><tr><td>Turnstile or reCAPTCHA secret</td><td><strong>Settings → Spam Protection → Captchas</strong></td></tr><tr><td>Which sites a form group applies to</td><td><strong>Settings → Form Groups</strong> (project config)</td></tr><tr><td>A reusable starter layout for new forms</td><td><strong>Stencils</strong> — CP stencils in the database, or project stencils in YAML (<a href="/guides/control-panel-admin/stencils-for-repeatable-form-types">Stencils guide</a>)</td></tr><tr><td>Fields and notifications on a live form</td><td>Form builder (database) — or import/export between environments</td></tr><tr><td>French field labels on one site</td><td>Form builder site switcher (database overrides)</td></tr><tr><td>Stripe webhook proxy for local dev</td><td><code>paymentWebhookProxyUrl</code> in <code>formie.php</code></td></tr><tr><td>Mailchimp OAuth token</td><td>Integrations CP — reconnect after DB copy</td></tr></tbody></table><p>Integration settings can reference Craft env syntax (<code>$STRIPE_SECRET_KEY</code>) in the CP; values are resolved when Formie reads them, not stored in exported project YAML.</p><h2 id="after-copying-a-database-between-environments" tabindex="-1">After Copying a Database Between Environments <a class="header-anchor" href="#after-copying-a-database-between-environments" aria-label="Permalink to &quot;After Copying a Database Between Environments&quot;">​</a></h2><p>Database copies are common for staging refreshes or bad promotions. Treat this as a checklist, not an automatic sync:</p><ul><li>Re-enter captcha secrets and integration tokens (or confirm env-var-backed settings resolve correctly)</li><li>Review spam keywords — staging test rules should not block real users on production</li><li>Reconnect OAuth integrations (tokens are environment-specific)</li><li>Verify form handles and group assignments still make sense on the target site set</li></ul><p>Project config sync alone does not undo a bad database copy.</p><h2 id="stencils-—-two-types-two-scopes" tabindex="-1">Stencils — Two Types, Two Scopes <a class="header-anchor" href="#stencils-—-two-types-two-scopes" aria-label="Permalink to &quot;Stencils — Two Types, Two Scopes&quot;">​</a></h2><p>Stencils confuse people because both kinds look similar in the CP:</p><table tabindex="0"><thead><tr><th>Type</th><th>Scope</th><th>On production with <code>allowAdminChanges: false</code></th></tr></thead><tbody><tr><td>CP stencil</td><td>Database</td><td>Editable when admin changes are allowed</td></tr><tr><td>Project stencil</td><td>Project config</td><td>View-only; use <strong>Save a copy</strong> to fork into a CP stencil</td></tr></tbody></table><p>Handles must be unique across both types. See <a href="/guides/control-panel-admin/stencils-for-repeatable-form-types">Stencils for repeatable form types</a> for when to use each.</p><h2 id="security-habits-worth-keeping" tabindex="-1">Security Habits Worth Keeping <a class="header-anchor" href="#security-habits-worth-keeping" aria-label="Permalink to &quot;Security Habits Worth Keeping&quot;">​</a></h2><ul><li>Prefer env vars for API keys where the CP supports <code>$VAR</code> syntax</li><li>Do not commit CP-stored secrets into project YAML</li><li>Keep <code>allowedGraphqlOrigins</code> narrow for headless forms</li><li>Leave <code>enableCsrfValidationForGuests</code> enabled unless you have a documented exception</li></ul>',47)])])}const u=t(i,[["render",a]]);export{g as __pageData,u as default};
